import React from 'react';
import Blobs  from '../components/Blobs';
import Orb3D  from '../components/Orb3D';
import { useMoods, useThoughts } from '../hooks/useStorage';

const TRAP_ICONS = { 'Katastrofiering':'🌪️','Tankeläsning':'🔮','Svartvitt tänkande':'⬛','Övergeneralisering':'🔁','Känslomässigt resonerande':'💭','Personalisering':'🎯','Filtrerande':'🔍','Bör-tänkande':'📋' };
const MOOD_COLORS = { 1:'#f87171',2:'#fb923c',3:'#fbbf24',4:'#34d399',5:'#60a5fa' };
const AVG_EMOJI   = ['','😔','😟','😐','🙂','😄'];

export default function History({ setPage }) {
  const { moods, streak, avgMood } = useMoods();
  const { thoughts, trapCounts }   = useThoughts();
  const isEmpty = moods.length===0 && thoughts.length===0;

  if (isEmpty) return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'0 24px' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:32 }}>
          <Orb3D size={160} colors={['#304060','#101828','#4060a0']} speed={0.2} morphing={false} />
        </div>
        <h2 style={{ fontSize:32, fontWeight:700, color:'#fff', marginBottom:12 }}>Ingen data än</h2>
        <p style={{ fontSize:14, color:'rgba(255,255,255,0.4)', marginBottom:36 }}>Analysera en tanke eller gör din första incheckning.</p>
        <div style={{ display:'flex', gap:12, justifyContent:'center', flexWrap:'wrap' }}>
          <button onClick={()=>setPage('home')} style={{ padding:'12px 24px', borderRadius:100, background:'rgba(255,255,255,0.9)', color:'#0a0a0f', fontSize:13, fontWeight:600 }}>Analysera en tanke</button>
          <button onClick={()=>setPage('checkin')} className="glass" style={{ padding:'12px 24px', borderRadius:100, color:'rgba(255,255,255,0.6)', fontSize:13 }}>Daglig check-in</button>
        </div>
      </div>
    </div>
  );

  const maxTrap = Math.max(...Object.values(trapCounts), 1);

  return (
    <div style={{ minHeight:'100vh', position:'relative' }}>
      <Blobs />
      <div style={{ position:'relative', zIndex:1, padding:'80px 24px 64px', maxWidth:560, margin:'0 auto', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>

        {/* Big heading */}
        <h1 style={{ fontSize:'clamp(44px,9vw,68px)', fontWeight:700, letterSpacing:'-0.05em', lineHeight:0.88, color:'#fff', marginBottom:40 }}>
          DIN<br/><span style={{ color:'rgba(255,255,255,0.2)' }}>HISTORIK</span>
        </h1>

        {/* Stats — glass pills */}
        <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:10, marginBottom:32 }}>
          {[
            { val:`🔥 ${streak}`, label:'Dagars streak' },
            { val:thoughts.length, label:'Analyser' },
            { val:avgMood>0?`${AVG_EMOJI[Math.round(avgMood)]} ${avgMood}`:'–', label:'Snitt humör' },
          ].map(({val,label})=>(
            <div key={label} className="glass" style={{ borderRadius:18, padding:'18px 14px', textAlign:'center' }}>
              <div style={{ fontSize:22, fontWeight:700, color:'#fff', marginBottom:4, lineHeight:1 }}>{val}</div>
              <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.28)', letterSpacing:'0.12em', textTransform:'uppercase' }}>{label}</div>
            </div>
          ))}
        </div>

        {/* Mood chart */}
        {moods.length>0 && (
          <div className="glass" style={{ borderRadius:20, padding:'22px', marginBottom:12 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(255,255,255,0.28)', marginBottom:18 }}>Humör — senaste 14 dagarna</p>
            <div style={{ display:'flex', alignItems:'flex-end', gap:5, height:80 }}>
              {[...moods].reverse().map((m,i)=>(
                <div key={i} style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:4, height:'100%', justifyContent:'flex-end' }}>
                  <span style={{ fontSize:11 }}>{m.emoji}</span>
                  <div style={{ width:'100%', borderRadius:'4px 4px 0 0', background:MOOD_COLORS[m.score], height:`${(m.score/5)*100}%`, minHeight:4, boxShadow:`0 0 8px ${MOOD_COLORS[m.score]}66` }} />
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:7, color:'rgba(255,255,255,0.22)', whiteSpace:'nowrap' }}>
                    {new Date(m.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Trap frequency */}
        {Object.keys(trapCounts).length>0 && (
          <div className="glass" style={{ borderRadius:20, padding:'22px', marginBottom:12 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(255,255,255,0.28)', marginBottom:18 }}>Vanligaste tankefällor</p>
            {Object.entries(trapCounts).sort((a,b)=>b[1]-a[1]).map(([label,count])=>(
              <div key={label} style={{ display:'flex', alignItems:'center', gap:10, marginBottom:12 }}>
                <span style={{ fontSize:13, width:18, flexShrink:0 }}>{TRAP_ICONS[label]||'💭'}</span>
                <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(255,255,255,0.45)', flex:1, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{label}</span>
                <div style={{ width:72, height:3, background:'rgba(255,255,255,0.06)', borderRadius:2, flexShrink:0 }}>
                  <div style={{ height:'100%', borderRadius:2, background:'rgba(255,255,255,0.35)', width:`${(count/maxTrap)*100}%`, transition:'width .8s cubic-bezier(0.16,1,0.3,1)', boxShadow:'0 0 6px rgba(255,255,255,0.15)' }} />
                </div>
                <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(255,255,255,0.25)', width:18, textAlign:'right' }}>{count}</span>
              </div>
            ))}
          </div>
        )}

        {/* Thought entries */}
        {thoughts.length>0 && (
          <>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(255,255,255,0.28)', margin:'28px 0 12px' }}>Tidigare analyser</p>
            {thoughts.map(t=>(
              <div key={t.id} className="glass" style={{ borderRadius:18, padding:'18px', marginBottom:10 }}>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:10 }}>
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(255,255,255,0.5)' }}>{t.trap_icon||'💭'} {t.trap_label}</span>
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.22)' }}>{new Date(t.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</span>
                </div>
                <p style={{ fontSize:13, color:'rgba(255,255,255,0.3)', fontStyle:'italic', marginBottom:10, lineHeight:1.6 }}>"{t.user_text?.slice(0,120)}{t.user_text?.length>120?'...':''}"</p>
                <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.12em', textTransform:'uppercase', color:'rgba(255,255,255,0.22)', marginBottom:5 }}>Omramning</p>
                <p style={{ fontSize:13, color:'rgba(255,255,255,0.6)', lineHeight:1.65, fontWeight:300 }}>{t.reframe}</p>
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
